style.css:
@-moz-document url-prefix("http://"), url-prefix("https://") {
* {
        background-color: #000000 !important;
        color: #00ffff !important;
        border-color: #00ffff !important;
    }
    
    a {
        color: #00ffff !important;
    }
    
    input, textarea, select, button {
        background-color: #000000 !important;
        color: #00ffff !important;
        border: 1px solid #00ffff !important;
    }
}
